scripts.continued_fraction_numerator:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']  # This will be passed as a list

    # Initialize p_(-1) = 1 and p_0 = a_0
    p_minus_1 = 1
    p_0 = terms[0]

    if len(terms) == 1:
        return float(p_0)

    # Use the recurrence relation: p_i = a_i * p_(i-1) + p_(i-2)
    p_prev_prev = p_minus_1
    p_prev = p_0

    for i in range(1, len(terms)):
        p_curr = terms[i] * p_prev + p_prev_prev
        p_prev_prev = p_prev
        p_prev = p_curr

    return float(p_prev)

