def solve(inputs: dict) -> float:
    X = int(inputs['SEED'])
    A = int(inputs['A'])
    B = int(inputs['B'])
    M = int(inputs['M'])
    K = int(inputs['K'])

    for _ in range(K):
        X = (A * X + B) % M

    return float(X)

